particles[i].force = glm::vec3(0.0f);
glm::ivec3 cell = getCell(&particles[i], h);

for (int dx = -1; dx <= 1; ++dx) {
    for (int dy = -1; dy <= 1; ++dy) {
        for (int dz = -1; dz <= 1; ++dz) {
            uint32_t cellHash = getHash(cell + glm::ivec3(dx, dy, dz));
            uint32_t pjIdx = particleTable[cellHash];
            if (pjIdx == NO_PARTICLE) {
                continue;
            }
            while (pjIdx < particleCount) {
                const Particle* pj = &particles[pjIdx];
                if (pj->hash != cellHash) {
                    break;
                }
                if (pjIdx != i) {
                    float dist2 = glm::length2(pj->position - particles[i].position);
                    if (dist2 < h2) {
                        float dist = std::sqrt(dist2);
                        glm::vec3 dir = (dist > 0.0f)
                            ? (pj->position - particles[i].position) / dist
                            : glm::vec3(0.0f);

                        // Pressure force
                        float pressureCoeff = -mass * (particles[i].pressure + pj->pressure)
                                              / (2.0f * pj->density) * spikyGrad;
                        glm::vec3 pressureForce = dir * pressureCoeff * std::pow(h - dist, 2.0f);
                        particles[i].force += pressureForce;

                        // Viscosity force
                        glm::vec3 velDiff = pj->velocity - particles[i].velocity;
                        glm::vec3 viscForce = viscosity * mass * (velDiff / pj->density)
                                              * spikyLap * (h - dist);
                        particles[i].force += viscForce;
                    }
                }
                ++pjIdx;
            }
        }
    }
}

